def replace_specialchar(text):
    return text.replace(' ', ':').replace(',', ':').replace('.', ':')

# Test case
assert replace_specialchar('Python language, Programming language.') == ('Python:language::Programming:language:')

def tuple_to_dict(t):
    """
    Converts a tuple of integers into a dictionary where each odd-indexed element 
    is the key and the following even-indexed element is the value.

    Example:
        Input:  (1, 5, 7, 10, 13, 5)
        Output: {1: 5, 7: 10, 13: 5}
    """
    return dict(zip(t[::2], t[1::2]))

