def find_max_length(list_of_lists):
    if not list_of_lists:
        return (0, [])

    max_len = 0
    max_list = []

    for sublist in list_of_lists:
        if len(sublist) > max_len:
            max_len = len(sublist)
            max_list = sublist

    return (max_len, max_list)

# Test case
assert find_max_length([[0], [1, 3], [5, 7], [9, 11], [13, 15, 17]]) == (3, [13, 15, 17])

def highest_Power_of_2(n):
    if n <= 0:
        return 0

    power = 1
    while power * 2 <= n:
        power *= 2

    return power

# Test case
assert highest_Power_of_2(10) == 8

def replace_spaces(text: str) -> str:
    """
    Replaces spaces in the string with underscores and vice versa.

    Args:
        text (str): The input string.

    Returns:
        str: The modified string with swapped spaces and underscores.
    """
    result = []
    for char in text:
        if char == ' ':
            result.append('_')
        elif char == '_':
            result.append(' ')
        else:
            result.append(char)
    return ''.join(result)

# Example usage and assertion
assert replace_spaces('Jumanji The Jungle') == 'Jumanji_The_Jungle'

