def sequential_search(arr, element):
    """
    Takes in an array and an element.
    Returns a tuple (is_found, index) where:
    - is_found is True if the element is in the array, False otherwise.
    - index is the position of the element if found, or -1 if not found.
    """
    for index, value in enumerate(arr):
        if value == element:
            return (True, index)
    return (False, -1)

# Example usage and assertion based on the problem description
assert sequential_search([11, 23, 58, 31, 56, 77, 43, 12, 65, 19], 31) == (True, 3)

def largest_subset(nums):
    if not nums:
        return 0

    # Sort the list to make it easier to check divisibility
    nums.sort()

    n = len(nums)
    dp = [1] * n  # dp[i] represents the size of the largest subset ending at index i

    for i in range(n):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

# Test case
assert largest_subset([1, 3, 6, 13, 17, 18]) == 4

import heapq

def heap_queue_largest(numbers, n):
    """
    Find the n largest integers from a given list of numbers, returned in descending order.

    Parameters:
    numbers (list): A list of numbers.
    n (int): The number of largest elements to find.

    Returns:
    list: A list of the n largest integers in descending order.
    """
    if n <= 0:
        return []
    if n >= len(numbers):
        return sorted(numbers, reverse=True)

    # Use a min-heap to keep track of the n largest elements seen so far
    heap = numbers[:n]
    heapq.heapify(heap)

    for num in numbers[n:]:
        if num > heap[0]:
            heapq.heapreplace(heap, num)

    return sorted(heap, reverse=True)

# Example usage and assertion
assert heap_queue_largest([25, 35, 22, 85, 14, 65, 75, 22, 58], 3) == [85, 75, 65]

def Find_Max_Length(matrix):
    max_length = 0
    for sublist in matrix:
        if len(sublist) > max_length:
            max_length = len(sublist)
    return max_length

# Test case
assert Find_Max_Length([[1],[1,4],[5,6,7,8]]) == 4

def reverse_vowels(s: str) -> str:
    vowels = set('aeiouAEIOU')
    chars = list(s)
    left, right = 0, len(chars) - 1

    while left < right:
        if chars[left] not in vowels:
            left += 1
        elif chars[right] not in vowels:
            right -= 1
        else:
            chars[left], chars[right] = chars[right], chars[left]
            left += 1
            right -= 1

    return ''.join(chars)

# Example usage and assertion
assert reverse_vowels("Python") == "Python"
